def solve(x, heads):
    import numpy as np
    x=np.asarray(x,dtype=float); t,d=x.shape
    if heads<1 or d%heads:raise ValueError("invalid heads")
    dh=d//heads; out=[]
    for h in range(heads):
        z=x[:,h*dh:(h+1)*dh]; scores=z@z.T/np.sqrt(dh)
        scores=np.where(np.triu(np.ones((t,t),dtype=bool),1),-np.inf,scores)
        e=np.exp(scores-scores.max(axis=-1,keepdims=True)); out.append((e/e.sum(axis=-1,keepdims=True))@z)
    return np.concatenate(out,axis=-1).tolist()
